solution.java:
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int stock = in.nextInt();
        int minReserve = in.nextInt();
        if (stock < minReserve) {
            System.out.println(minReserve * 2 - stock);
        } else {
            System.out.println(0);
        }
    }
}

solution.cpp:
#include <iostream>
using namespace std;

int main() {
    int stock, min_reserve;
    cin >> stock >> min_reserve;
    if (stock < min_reserve) {
        cout << min_reserve * 2 - stock << "\n";
    } else {
        cout << 0 << "\n";
    }
    return 0;
}
